package com.fooddelivery.auth; import jakarta.persistence.*; import lombok.*; @Entity @Table(name="users") @Getter @Setter @NoArgsConstructor public class User{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(unique=true,nullable=false) String email; @Column(nullable=false) String password; @Column(nullable=false) String fullName; String address; String phoneNumber; @Enumerated(EnumType.STRING) Role role=Role.CUSTOMER; enum Role{CUSTOMER,RESTAURANT_OWNER,ADMIN}}